const cart = []; document.querySelectorAll('.buy').forEach(b => b.addEventListener('click',()=>{cart.push(b.dataset.name); $('#cart-count').textContent=cart.length; $('#cart-list').textContent=cart.join(', '); b.textContent='Добавлено ✓';})); $('#cart-toggle')?.addEventListener('click',()=>{$('#cart').hidden=!$('#cart').hidden; if(!$('#cart').hidden) $('#cart').scrollIntoView({block:'nearest'});});
